--
-- Name: aplicar_impacto_cidadela(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aplicar_impacto_cidadela() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    impacto JSONB;
    item_impacto JSONB;
BEGIN
    -- Busca o impacto configurado no item da rota
    SELECT impacto_cidadela INTO impacto FROM public.clube_rota_itens WHERE id = NEW.item_id;
    
    IF impacto IS NOT NULL AND jsonb_array_length(impacto) > 0 THEN
        FOR item_impacto IN SELECT * FROM jsonb_array_elements(impacto)
        LOOP
            INSERT INTO public.cidadela_mapa_vivo (user_id, distrito, nivel, historico)
            VALUES (
                NEW.user_id, 
                item_impacto->>'distrito', 
                (item_impacto->>'intensidade')::integer,
                jsonb_build_array(jsonb_build_object('data', now(), 'origem', 'rota_item_concluido', 'item_id', NEW.item_id, 'tipo', item_impacto->>'tipo_impacto'))
            )
            ON CONFLICT (user_id, distrito) DO UPDATE
            SET 
                nivel = cidadela_mapa_vivo.nivel + (item_impacto->>'intensidade')::integer,
                historico = cidadela_mapa_vivo.historico || jsonb_build_object('data', now(), 'origem', 'rota_item_concluido', 'item_id', NEW.item_id, 'tipo', item_impacto->>'tipo_impacto'),
                ultima_atualizacao = now();
        END LOOP;
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: apply_pending_matricula(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_pending_matricula() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  pending RECORD;
BEGIN
  -- Find pending enrollment for this email
  SELECT * INTO pending
  FROM public.matriculas_pendentes
  WHERE email = NEW.email
    AND processado = false
  ORDER BY created_at DESC
  LIMIT 1;

  IF FOUND THEN
    -- Create enrollment
    INSERT INTO public.matriculas (user_id, curso_id, ativa, data_inicio)
    VALUES (NEW.id, pending.curso_id, true, now())
    ON CONFLICT (user_id, curso_id) DO UPDATE SET ativa = true;

    -- Update user portal level
    UPDATE public.user_roles
    SET portal = pending.portal_destino
    WHERE user_id = NEW.id;

    -- Mark pending as processed
    UPDATE public.matriculas_pendentes
    SET processado = true, updated_at = now()
    WHERE id = pending.id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: archive_previous_active_gesto(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_previous_active_gesto() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'ativo' THEN
    UPDATE public.gestos_integracao
    SET status = 'integrado', updated_at = now()
    WHERE cliente_id = NEW.cliente_id
      AND owner_id = NEW.owner_id
      AND status = 'ativo'
      AND id != NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: auto_publish_episode_to_circulo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_publish_episode_to_circulo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Only trigger when status changes to 'published'
  IF NEW.status = 'published' AND (OLD.status IS NULL OR OLD.status != 'published') THEN
    -- Only for clube_livro type with a linked ciclo
    IF NEW.tipo_episodio = 'clube_livro' AND NEW.ciclo_id IS NOT NULL THEN
      -- Insert into clube_livro_escutas (travessia content)
      INSERT INTO public.clube_livro_escutas (
        ciclo_id, titulo, descricao, tipo, audio_url, 
        texto_conteudo, duracao_segundos, ativo, ordem
      ) VALUES (
        NEW.ciclo_id,
        COALESCE(NEW.titulo, NEW.livro),
        NEW.descricao,
        'audio',
        COALESCE(NEW.audio_final_url, NEW.audio_full_url),
        NEW.roteiro_completo,
        NEW.duracao_segundos,
        true,
        COALESCE(
          (SELECT MAX(ordem) + 1 FROM public.clube_livro_escutas WHERE ciclo_id = NEW.ciclo_id),
          1
        )
      );

      -- Notify admin/students via notifications table
      INSERT INTO public.notifications (user_id, type, title, body)
      SELECT 
        p.id,
        'info',
        '🎧 Nova escuta disponível',
        COALESCE(NEW.titulo, NEW.livro) || ' foi publicada na Travessia.'
      FROM public.profiles p
      JOIN public.user_roles ur ON ur.user_id = p.id
      WHERE ur.portal NOT IN ('visitante');
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: bootstrap_cliente_jardim_base(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bootstrap_cliente_jardim_base() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Only create a bare jardim_heroina container (inactive, empty).
  -- Session cases, journeys, maps, cidadela are NOT created here.
  -- They are generated after the initial cartography is completed.
  INSERT INTO public.jardim_heroina (
    therapist_id,
    client_id,
    status
  )
  VALUES (
    NEW.terapeuta_id,
    NEW.id,
    'inactive'
  );

  RETURN NEW;
END;
$$;


--
-- Name: can_access_agent(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_agent(_user_id uuid, _agent_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM agentes a 
    WHERE a.id = _agent_id 
      AND a.status = 'ativo'
      AND has_portal_access(_user_id, a.portal_minimo)
  )
$$;


--
-- Name: can_access_sala(uuid, public.nivel_sala); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_sala(_user_id uuid, _nivel_minimo public.nivel_sala) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE get_user_nivel_sala(_user_id)
    WHEN 'NIVEL_3' THEN true
    WHEN 'NIVEL_2' THEN _nivel_minimo IN ('NIVEL_0', 'NIVEL_1', 'NIVEL_2')
    WHEN 'NIVEL_1' THEN _nivel_minimo IN ('NIVEL_0', 'NIVEL_1')
    WHEN 'NIVEL_0' THEN _nivel_minimo = 'NIVEL_0'
    ELSE false
  END
$$;


--
-- Name: can_receive_upsell_offer(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_receive_upsell_offer(p_user_id uuid, p_segment_to text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_last_offer TIMESTAMP WITH TIME ZONE;
    v_refusals INTEGER;
BEGIN
    SELECT MAX(last_offered_at), MAX(refusal_count) 
    INTO v_last_offer, v_refusals
    FROM public.upsell_opportunities
    WHERE user_id = p_user_id AND segment_to = p_segment_to;

    -- Regra: Não insistir se houve oferta nos últimos 30 dias
    IF v_last_offer IS NOT NULL AND v_last_offer > now() - INTERVAL '30 days' THEN
        RETURN FALSE;
    END IF;

    -- Regra: Se teve mais de 3 recusas, pausar por mais tempo (60 dias)
    IF v_refusals >= 3 AND v_last_offer > now() - INTERVAL '60 days' THEN
        RETURN FALSE;
    END IF;

    RETURN TRUE;
END;
$$;


--
-- Name: cancel_subscription(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_subscription(user_id_param uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE profiles
  SET 
    subscription_status = 'expired',
    portal = 'visitante'
  WHERE id = user_id_param;
  
  UPDATE user_roles
  SET portal = 'visitante'
  WHERE user_id = user_id_param;
END;
$$;


--
-- Name: check_and_expire_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_and_expire_access() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  expired_count INTEGER;
BEGIN
  -- Atualizar usuários com acesso expirado
  UPDATE profiles
  SET 
    portal = 'visitante',
    subscription_status = 'expired'
  WHERE 
    subscription_status != 'active'
    AND access_expires_at IS NOT NULL
    AND access_expires_at < NOW()
    AND portal != 'visitante';
  
  GET DIAGNOSTICS expired_count = ROW_COUNT;
  
  RETURN expired_count;
END;
$$;


--
-- Name: check_case_limit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_case_limit(_therapist_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN get_user_portal(_therapist_id) = 'admin' THEN true
    ELSE (
      -- Check if limit is -1 (unlimited)
      (SELECT COALESCE(max_cases, -1) FROM plan_limits WHERE portal = get_user_portal(_therapist_id)) = -1
      OR
      -- Count active cases and compare to limit
      (
        SELECT COUNT(*) FROM session_cases 
        WHERE therapist_id = _therapist_id AND status != 'archived'
      ) < (
        SELECT COALESCE(max_cases, -1) FROM plan_limits WHERE portal = get_user_portal(_therapist_id)
      )
    )
  END
$$;


--
-- Name: client_has_active_jardim(uuid); Type: FUNCTION; Schema: public; Owner: -
