--
-- Name: dispatch_notification_channels(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_notification_channels() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Use pg_net to call the dispatch edge function asynchronously
  PERFORM net.http_post(
    url := current_setting('app.settings.supabase_url', true) || '/functions/v1/dispatch-notification',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || current_setting('app.settings.service_role_key', true)
    ),
    body := jsonb_build_object('record', row_to_json(NEW))
  );
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Don't block notification insert if dispatch fails
  RAISE WARNING 'dispatch_notification_channels failed: %', SQLERRM;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_single_active_season(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_single_active_season() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'ativa' AND (OLD.status IS NULL OR OLD.status != 'ativa') THEN
    UPDATE public.oracular_seasons
    SET status = 'concluida'
    WHERE status = 'ativa' AND id != NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


