    AND a.status = 'ativo';
$$;


--
-- Name: get_case_quota(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_case_quota(_therapist_id uuid) RETURNS TABLE(used_cases bigint, max_cases integer, can_create boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    (SELECT COUNT(*) FROM session_cases WHERE therapist_id = _therapist_id AND status != 'archived') as used_cases,
    (SELECT COALESCE(pl.max_cases, -1) FROM plan_limits pl WHERE pl.portal = get_user_portal(_therapist_id)) as max_cases,
    check_case_limit(_therapist_id) as can_create
$$;


--
-- Name: get_clube_proximo_passo(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_clube_proximo_passo(p_user_id uuid, p_rota_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_ultimo_passo_concluido UUID;
    v_proximo_passo UUID;
BEGIN
    -- Busca o último passo concluído nesta rota
    SELECT passo_id INTO v_ultimo_passo_concluido
    FROM public.clube_progresso_passos p
    JOIN public.clube_rota_itens i ON i.id = p.passo_id
    WHERE p.user_id = p_user_id AND i.rota_id = p_rota_id
    ORDER BY i.ordem DESC
    LIMIT 1;

    -- Se não tem nenhum, pega o primeiro
    IF v_ultimo_passo_concluido IS NULL THEN
        SELECT id INTO v_proximo_passo
        FROM public.clube_rota_itens
        WHERE rota_id = p_rota_id
        ORDER BY ordem ASC
        LIMIT 1;
    ELSE
        -- Pega o próximo por ordem
        SELECT id INTO v_proximo_passo
        FROM public.clube_rota_itens
        WHERE rota_id = p_rota_id 
          AND ordem > (SELECT ordem FROM public.clube_rota_itens WHERE id = v_ultimo_passo_concluido)
        ORDER BY ordem ASC
        LIMIT 1;
    END IF;

    RETURN v_proximo_passo;
END;
$$;


