--
-- Name: content_blocks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.content_blocks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    context_type public.block_context_type NOT NULL,
    context_id uuid NOT NULL,
    block_type public.content_block_type NOT NULL,
    ordem integer DEFAULT 0 NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    portal_minimo public.portal_type DEFAULT 'visitante'::public.portal_type NOT NULL,
    content jsonb DEFAULT '{}'::jsonb NOT NULL,
    agente_id uuid,
    titulo text,
    descricao text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    cloudflare_video_id text
);


--
-- Name: get_content_blocks(public.block_context_type, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_content_blocks(_context_type public.block_context_type, _context_id uuid, _user_id uuid DEFAULT NULL::uuid) RETURNS SETOF public.content_blocks
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT * FROM public.content_blocks
  WHERE context_type = _context_type
    AND context_id = _context_id
    AND ativo = true
    AND (
      _user_id IS NULL 
      OR has_portal_access(_user_id, portal_minimo)
    )
  ORDER BY ordem ASC;
$$;


--
-- Name: get_user_access_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_access_status(_user_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT COALESCE(
        (SELECT 
            CASE 
                WHEN s.status = 'active' THEN 'member_continuity'
                WHEN s.status = 'past_due' THEN 'member_continuity' -- carência
                WHEN s.status = 'canceled' AND s.current_period_end > now() THEN 'member_continuity'
                ELSE 'member_free'
            END
        FROM public.subscriptions s
        WHERE s.user_id = _user_id
        ORDER BY s.created_at DESC
        LIMIT 1),
        'visitor'
    )
$$;


--
-- Name: get_user_nivel_sala(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_nivel_sala(_user_id uuid) RETURNS public.nivel_sala
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE get_user_portal(_user_id)
    WHEN 'visitante' THEN 'NIVEL_0'::nivel_sala
    WHEN 'mentorada' THEN 'NIVEL_1'::nivel_sala
    WHEN 'aluna_formacao' THEN 'NIVEL_1'::nivel_sala
    WHEN 'assinante' THEN 'NIVEL_2'::nivel_sala
    WHEN 'oracula' THEN 'NIVEL_2'::nivel_sala
    WHEN 'admin' THEN 'NIVEL_3'::nivel_sala
    -- Legacy fallback
    WHEN 'pre_iniciada' THEN 'NIVEL_1'::nivel_sala
    WHEN 'iniciada' THEN 'NIVEL_2'::nivel_sala
    ELSE 'NIVEL_0'::nivel_sala
  END
$$;


--
-- Name: get_user_portal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_portal(_user_id uuid) RETURNS public.portal_type
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT portal FROM public.user_roles WHERE user_id = _user_id),
    'visitante'::portal_type
  )
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.profiles (id, email, nome)
  VALUES (NEW.id, NEW.email, NEW.raw_user_meta_data ->> 'nome');
  
  INSERT INTO public.user_roles (user_id, portal)
  VALUES (NEW.id, 'visitante');
  
  RETURN NEW;
END;
$$;


--
-- Name: has_course_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_course_access(_user_id uuid, _course_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    -- Admin always has access
    get_user_portal(_user_id) = 'admin'
    OR
    -- Free courses with appropriate portal level
    EXISTS (
      SELECT 1 FROM public.courses c
      WHERE c.id = _course_id
        AND c.pricing_model = 'free'
        AND c.publicado = true
        AND has_portal_access(_user_id, c.portal_minimo)
    )
    OR
    -- User has active enrollment
    EXISTS (
      SELECT 1 FROM public.course_enrollments e
      WHERE e.user_id = _user_id
        AND e.course_id = _course_id
        AND e.ativo = true
        AND (e.data_fim IS NULL OR e.data_fim > now())
    )
    OR
    -- Subscription-based course with active subscription + enrollment/matricula
    EXISTS (
      SELECT 1 FROM public.courses c
      JOIN public.subscriptions s ON s.user_id = _user_id
      WHERE c.id = _course_id
        AND c.pricing_model = 'subscription'
        AND c.publicado = true
        AND s.status IN ('active', 'past_due')
        AND has_portal_access(_user_id, c.portal_minimo)
    )
$$;


--
-- Name: has_oracle_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_oracle_access(_user_id uuid, _oracle_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    get_user_portal(_user_id) = 'admin'
    OR EXISTS (
      SELECT 1 FROM public.oracle_decks d
      WHERE d.id = _oracle_id
        AND d.status = 'published'
        AND has_portal_access(_user_id, d.minimum_portal)
    )
$$;


--
-- Name: has_portal_access(uuid, public.portal_type); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_portal_access(_user_id uuid, _min_portal public.portal_type) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE 
    WHEN _min_portal = 'visitante' THEN true
    WHEN _min_portal = 'mentorada' THEN public.get_user_portal(_user_id) IN ('mentorada', 'aluna_formacao', 'assinante', 'oracula', 'admin')
    WHEN _min_portal = 'aluna_formacao' THEN public.get_user_portal(_user_id) IN ('aluna_formacao', 'assinante', 'oracula', 'admin')
    WHEN _min_portal = 'assinante' THEN public.get_user_portal(_user_id) IN ('assinante', 'oracula', 'admin')
    WHEN _min_portal = 'oracula' THEN public.get_user_portal(_user_id) IN ('oracula', 'admin')
    WHEN _min_portal = 'admin' THEN public.get_user_portal(_user_id) = 'admin'
    -- Legacy fallback for old values
    WHEN _min_portal = 'pre_iniciada' THEN public.get_user_portal(_user_id) IN ('mentorada', 'aluna_formacao', 'assinante', 'oracula', 'admin')
    WHEN _min_portal = 'iniciada' THEN public.get_user_portal(_user_id) IN ('oracula', 'admin')
    ELSE false
  END
$$;


--
-- Name: is_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin(_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id AND portal = 'admin'
  )
$$;


--
-- Name: is_lesson_available(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_lesson_available(_user_id uuid, _lesson_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    -- Admin always has access
    get_user_portal(_user_id) = 'admin'
    OR
    EXISTS (
      SELECT 1 
      FROM public.course_lessons l
      JOIN public.course_modules m ON m.id = l.module_id
      JOIN public.courses c ON c.id = m.course_id
      LEFT JOIN public.course_enrollments e ON e.course_id = c.id AND e.user_id = _user_id
      WHERE l.id = _lesson_id
        AND l.publicado = true
        AND m.publicado = true
        AND c.publicado = true
        AND has_course_access(_user_id, c.id)
        AND (
          -- No drip restrictions
          (m.disponivel_em IS NULL AND m.dias_apos_matricula IS NULL)
          -- Date-based drip
          OR (m.disponivel_em IS NOT NULL AND m.disponivel_em <= CURRENT_DATE)
          -- Days after enrollment drip
          OR (m.dias_apos_matricula IS NOT NULL AND e.data_inicio IS NOT NULL 
              AND (e.data_inicio + (m.dias_apos_matricula || ' days')::INTERVAL) <= now())
        )
    )
$$;


--
-- Name: is_matriculada(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_matriculada(_user_id uuid, _curso_id text DEFAULT 'formacao_oracula'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.matriculas
    WHERE user_id = _user_id
      AND curso_id = _curso_id
      AND ativa = true
      AND (data_fim IS NULL OR data_fim > now())
  )
$$;


