-- Name: is_profissional_confirmada(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_profissional_confirmada(_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
