--
-- Name: view_user_stagnation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.view_user_stagnation AS
 WITH user_base AS (
         SELECT p.id AS user_id,
            p.nome,
            p.email,
            p.portal,
            p.created_at AS signup_date,
            s.plan_id,
            s.status AS subscription_status,
            ( SELECT max(ai_interaction_logs.created_at) AS max
                   FROM public.ai_interaction_logs
                  WHERE (ai_interaction_logs.user_id = p.id)) AS last_ai_use,
            ( SELECT max(clube_rota_progresso.updated_at) AS max
                   FROM public.clube_rota_progresso
                  WHERE (clube_rota_progresso.user_id = p.id)) AS last_clube_activity,
            ( SELECT count(*) AS count
                   FROM public.cartografia_psiquica
                  WHERE (cartografia_psiquica.user_id = p.id)) AS total_cartografias,
            ( SELECT max(cartografia_psiquica.created_at) AS max
                   FROM public.cartografia_psiquica
                  WHERE (cartografia_psiquica.user_id = p.id)) AS last_cartografia,
            ( SELECT count(*) AS count
                   FROM public.co_jardim_entries
                  WHERE (s.user_id = p.id)) AS total_jardim,
            (EXISTS ( SELECT 1
                   FROM public.profiles
                  WHERE ((profiles.id = p.id) AND (profiles.portal = 'aluna'::text)))) AS is_aluna,
            (EXISTS ( SELECT 1
                   FROM public.profiles
                  WHERE ((profiles.id = p.id) AND (profiles.portal = 'terapeuta'::text)))) AS is_terapeuta
           FROM (public.profiles p
             LEFT JOIN public.subscriptions s ON ((s.user_id = p.id)))
        ), risk_calculations AS (
         SELECT user_base.user_id,
            user_base.nome,
            user_base.email,
            user_base.portal,
            user_base.signup_date,
            user_base.plan_id,
            user_base.subscription_status,
            user_base.last_ai_use,
            user_base.last_clube_activity,
            user_base.total_cartografias,
            user_base.last_cartografia,
            user_base.total_jardim,
            user_base.is_aluna,
            user_base.is_terapeuta,
                CASE
                    WHEN ((user_base.subscription_status IS NULL) OR (user_base.subscription_status <> 'active'::text)) THEN LEAST(100, ((
                    CASE
                        WHEN (user_base.total_cartografias = 0) THEN 40
                        ELSE 0
                    END +
                    CASE
                        WHEN (user_base.total_jardim = 0) THEN 30
                        ELSE 0
                    END) +
                    CASE
                        WHEN ((user_base.signup_date < (now() - '3 days'::interval)) AND (user_base.total_cartografias = 0)) THEN 30
                        ELSE 0
                    END))
                    ELSE 0
                END AS conversion_risk_score,
                CASE
                    WHEN ((user_base.subscription_status = 'active'::text) AND (user_base.portal = 'aluna'::text)) THEN LEAST(100, ((
                    CASE
                        WHEN ((user_base.last_clube_activity < (now() - '7 days'::interval)) OR (user_base.last_clube_activity IS NULL)) THEN 50
                        ELSE 0
                    END +
                    CASE
                        WHEN ((user_base.last_ai_use < (now() - '10 days'::interval)) OR (user_base.last_ai_use IS NULL)) THEN 30
                        ELSE 0
                    END) +
                    CASE
                        WHEN ((user_base.last_cartografia < (now() - '15 days'::interval)) OR (user_base.last_cartografia IS NULL)) THEN 20
                        ELSE 0
                    END))
                    ELSE 0
                END AS churn_risk_score,
                CASE
                    WHEN ((user_base.subscription_status = 'active'::text) AND user_base.is_terapeuta) THEN LEAST(100, (
                    CASE
                        WHEN (user_base.last_ai_use IS NULL) THEN 70
                        ELSE 0
                    END +
                    CASE
                        WHEN (user_base.last_ai_use < (now() - '5 days'::interval)) THEN 30
                        ELSE 0
                    END))
                    ELSE 0
                END AS saas_value_risk_score
           FROM user_base
        )
 SELECT user_id,
    nome,
    email,
    portal,
    signup_date,
    plan_id,
    subscription_status,
    last_ai_use,
    last_clube_activity,
    total_cartografias,
    last_cartografia,
    total_jardim,
    is_aluna,
    is_terapeuta,
    conversion_risk_score,
    churn_risk_score,
    saas_value_risk_score,
        CASE
            WHEN (saas_value_risk_score > 60) THEN 'Terapeuta Subutilizando IA'::text
            WHEN (churn_risk_score > 60) THEN 'Assinante em Abandono Iminente'::text
            WHEN (conversion_risk_score > 60) THEN 'Lead Travado no Onboarding'::text
            WHEN (saas_value_risk_score > 30) THEN 'Uso Irregular do SaaS'::text
            WHEN (churn_risk_score > 30) THEN 'Queda de Engajamento no Clube'::text
            WHEN (conversion_risk_score > 30) THEN 'Potencial Churn no Funil'::text
            ELSE 'Engajamento Normal'::text
        END AS action_reason,
        CASE
            WHEN (saas_value_risk_score > 60) THEN 'Tutorial: Como usar a Cabine na prática'::text
            WHEN (churn_risk_score > 60) THEN 'Mensagem de Resgate: Próximo Passo na Rota'::text
            WHEN (conversion_risk_score > 60) THEN 'Incentivo: Concluir Cartografia Psíquica'::text
            WHEN (saas_value_risk_score > 30) THEN 'Sugestão de Novo Modelo de IA'::text
            WHEN (churn_risk_score > 30) THEN 'Destaque da Semana no Clube'::text
            WHEN (conversion_risk_score > 30) THEN 'Tutorial: Primeiros Passos'::text
            ELSE 'Monitorar Apenas'::text
        END AS recommended_action,
        CASE
            WHEN ((saas_value_risk_score > 60) OR (churn_risk_score > 60)) THEN 'Suporte Manual'::text
            WHEN (conversion_risk_score > 60) THEN 'E-mail'::text
            WHEN ((saas_value_risk_score > 30) OR (churn_risk_score > 30) OR (conversion_risk_score > 30)) THEN 'Notificação'::text
            ELSE 'Ignorar'::text
        END AS suggested_channel,
        CASE
            WHEN ((saas_value_risk_score > 60) OR (churn_risk_score > 60) OR (conversion_risk_score > 60)) THEN 'Alta'::text
            WHEN ((saas_value_risk_score > 30) OR (churn_risk_score > 30) OR (conversion_risk_score > 30)) THEN 'Média'::text
            ELSE 'Baixa'::text
        END AS priority_level,
    (EXISTS ( SELECT 1
           FROM public.admin_action_history
          WHERE ((admin_action_history.user_id = risk_calculations.user_id) AND (admin_action_history.action_type =
                CASE
                    WHEN (risk_calculations.saas_value_risk_score > 30) THEN 'tutorial_saas'::text
                    WHEN (risk_calculations.churn_risk_score > 30) THEN 'resgate_clube'::text
                    WHEN (risk_calculations.conversion_risk_score > 30) THEN 'onboarding_cartografia'::text
                    ELSE 'monitoramento'::text
                END)))) AS action_already_sent,
    COALESCE(last_ai_use, last_clube_activity, last_cartografia, signup_date) AS last_value_timestamp
   FROM risk_calculations;


--
-- Name: view_admin_action_performance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.view_admin_action_performance AS
 WITH action_outcomes AS (
         SELECT a.id AS action_id,
            a.user_id,
            a.action_type,
            a.channel,
            a.sent_at,
            a.sent_by,
            a.conversion_risk_at_action,
            a.churn_risk_at_action,
            a.saas_value_risk_at_action,
            v.conversion_risk_score AS current_conversion_risk,
            v.churn_risk_score AS current_churn_risk,
            v.saas_value_risk_score AS current_saas_value_risk,
            v.last_value_timestamp AS current_last_value,
            v.subscription_status AS current_sub_status,
            (v.last_value_timestamp > a.sent_at) AS returned_to_access,
                CASE
                    WHEN (a.conversion_risk_at_action > (0)::numeric) THEN ((v.conversion_risk_score)::numeric < a.conversion_risk_at_action)
                    WHEN (a.churn_risk_at_action > (0)::numeric) THEN ((v.churn_risk_score)::numeric < a.churn_risk_at_action)
                    WHEN (a.saas_value_risk_at_action > (0)::numeric) THEN ((v.saas_value_risk_score)::numeric < a.saas_value_risk_at_action)
                    ELSE false
                END AS reduced_score,
            ((a.conversion_risk_at_action > (0)::numeric) AND (v.subscription_status = 'active'::text)) AS converted,
            ((a.churn_risk_at_action > (0)::numeric) AND (v.subscription_status = 'active'::text)) AS prevented_churn
           FROM (public.admin_action_history a
             JOIN public.view_user_stagnation v ON ((v.user_id = a.user_id)))
        )
 SELECT action_type,
    channel,
    count(*) AS total_actions,
    count(*) FILTER (WHERE returned_to_access) AS total_returned,
    count(*) FILTER (WHERE reduced_score) AS total_score_reduced,
    count(*) FILTER (WHERE converted) AS total_converted,
    count(*) FILTER (WHERE prevented_churn) AS total_retained,
    round((((count(*) FILTER (WHERE (returned_to_access OR reduced_score OR converted OR prevented_churn)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 2) AS success_rate
   FROM action_outcomes
  GROUP BY action_type, channel;


--
-- Name: view_founder_financial_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.view_founder_financial_summary AS
 SELECT id,
    period_start,
    period_end,
    (((revenue_clube + revenue_saas) + revenue_formacao) + revenue_upsell) AS total_revenue,
    ((((cost_ia + cost_infra) + cost_stripe) + cost_ads) + cost_team) AS total_costs,
    ((((revenue_clube + revenue_saas) + revenue_formacao) + revenue_upsell) - (cost_stripe + cost_ia)) AS gross_profit,
    ((((revenue_clube + revenue_saas) + revenue_formacao) + revenue_upsell) - ((((cost_ia + cost_infra) + cost_stripe) + cost_ads) + cost_team)) AS net_profit,
        CASE
            WHEN ((((revenue_clube + revenue_saas) + revenue_formacao) + revenue_upsell) > 0) THEN round((((((((revenue_clube + revenue_saas) + revenue_formacao) + revenue_upsell) - ((((cost_ia + cost_infra) + cost_stripe) + cost_ads) + cost_team)))::numeric / ((((revenue_clube + revenue_saas) + revenue_formacao) + revenue_upsell))::numeric) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS net_margin_pct,
    churn_rate,
    ltv,
    cac,
    payback_period,
    new_sales,
    upgrades,
    cancellations,
    revenue_expansion,
    revenue_clube,
    revenue_saas,
    revenue_formacao,
    revenue_upsell,
    cost_ia,
    cost_infra,
    cost_stripe,
    cost_ads,
    cost_team
   FROM public.founder_financial_metrics;


--
-- Name: view_founder_real_financial_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.view_founder_real_financial_summary AS
 WITH monthly_agg AS (
         SELECT date_trunc('month'::text, (founder_financial_daily.date)::timestamp with time zone) AS period_start,
            sum(((founder_financial_daily.new_sales_value + founder_financial_daily.renewals_value) - founder_financial_daily.refunds_value)) AS total_revenue,
            sum(((((founder_financial_daily.cost_ia + founder_financial_daily.cost_stripe) + founder_financial_daily.cost_ads) + founder_financial_daily.cost_infra) + founder_financial_daily.cost_team)) AS total_costs,
            sum(founder_financial_daily.new_sales_value) AS revenue_new,
            sum(founder_financial_daily.renewals_value) AS revenue_renewals,
            sum(founder_financial_daily.cost_ia) AS total_cost_ia,
            sum(founder_financial_daily.cost_stripe) AS total_cost_stripe,
            sum(founder_financial_daily.cost_ads) AS total_cost_ads,
            sum(founder_financial_daily.cost_infra) AS total_cost_infra,
            sum(founder_financial_daily.cost_team) AS total_cost_team,
            avg(founder_financial_daily.active_mrr) AS avg_mrr
           FROM public.founder_financial_daily
          GROUP BY (date_trunc('month'::text, (founder_financial_daily.date)::timestamp with time zone))
        )
 SELECT period_start,
    total_revenue,
    total_costs,
    revenue_new,
    revenue_renewals,
    total_cost_ia,
    total_cost_stripe,
    total_cost_ads,
    total_cost_infra,
    total_cost_team,
    avg_mrr,
    (total_revenue - total_costs) AS net_profit,
        CASE
            WHEN (total_revenue > (0)::numeric) THEN round((((total_revenue - total_costs) / total_revenue) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS net_margin_pct
   FROM monthly_agg;


